MAX_NAME_CHARS = 64


def greeting(name: str | None = None) -> str:
    if name is None:
        return "hello, demo"
    if len(name) > MAX_NAME_CHARS:
        raise ValueError(f"name exceeds the {MAX_NAME_CHARS}-character limit")
    return f"hello, {name}"
